"""Generate an honest demo report from aggregate local artifacts only."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def generate() -> None:
    """Write reproducible tables without reading datasets or running inference."""
    models = ROOT / "backend/models"
    metrics = json.loads((models / "metrics.json").read_text(encoding="utf-8"))
    lines = [
        "# Nigehbaan AI demo report",
        "",
        "Generated by `python -m ml.report_demo`; aggregate artifacts only.",
        "",
        "## Implemented",
        "",
        "Roman Urdu text preprocessing, TF-IDF NB/LR/SVM/RF comparison, LR/SVM ensemble, configurable rules, hybrid risk and partial LR word attribution. Static URL analysis never visits submitted URLs. React Analyze, Dashboard, Model Lab, Settings and About pages are connected to FastAPI. Image/PDF/audio/video extraction is implemented with bounded uploads and temporary-file cleanup.",
        "",
        "## Validation results",
        "",
        "These are source-specific validation results; custom text labels remain human-unverified. They are not final test or real-world accuracy estimates.",
        "",
        "| Text model | Macro-F1 |",
        "|---|---:|",
    ]
    lines += [f"| {row['name']} | {row['macro_f1']:.4f} |" for row in metrics["models"]]
    lines += [
        "",
        f"Active text model: `{metrics['best_model']}`.",
        "",
        "| URL model | Macro-F1 |",
        "|---|---:|",
    ]
    lines += [
        f"| {row['name']} | {row['macro_f1']:.4f} |"
        for row in metrics.get("url_models", [])
    ]
    lines += [
        "",
        f"Active URL model: `{metrics.get('best_url_model', 'unavailable')}`.",
    ]
    robust = ROOT / "docs/URL_ROBUSTNESS_RESULTS.json"
    if robust.exists():
        result = json.loads(robust.read_text(encoding="utf-8"))
        lines += [
            "",
            "## URL robustness experiment",
            "",
            "Candidate results do not imply promotion; the active model above comes from deployed metadata. Synthetic paths and hostname variants inherit benign labels as an assumption.",
            "",
            "| Candidate | Evaluation | Macro-F1 | Benign false-positive rate |",
            "|---|---|---:|---:|",
        ]
        for row in result["rows"]:
            for key, value in row.items():
                if isinstance(value, dict) and "macro_f1" in value:
                    lines.append(
                        f"| {row['name']} | {key} | {value['macro_f1']:.4f} | {value['benign_false_positive_rate']:.4f} |"
                    )
        lines += ["", result["limits"]]
    final_path = ROOT / "docs/FINAL_RESULTS.json"
    if final_path.exists():
        final = json.loads(final_path.read_text(encoding="utf-8"))
        lines += [
            "",
            "## One-shot test results",
            "",
            "| Evaluation | Macro-F1 | Rows |",
            "|---|---:|---:|",
        ]
        for name, row in [
            ("Text ML", final["text_test"]["ml"]),
            ("Text hybrid", final["text_test"]["hybrid"]),
            ("Synthetic custom hybrid", final["custom_holdout"]["hybrid"]),
            ("Static URL", final["url_test"]),
        ]:
            lines.append(f"| {name} | {row['macro_f1']:.4f} | {row['rows']} |")
        lines += ["", final["limitations"]]
    lines += [
        "",
        "## Privacy and limits",
        "",
        "No submitted message, transcript, phone number, media or URL is retained in history. Only high-risk metadata is retained. Abuse cues are masked. Models remain experimental; low risk does not establish safety. OCR can miss links. Synthetic English speech integration checks do not establish Urdu voice accuracy.",
        "",
        "## Remaining acceptance work",
        "",
        "Human label review, independently reviewed URL cases, realistic Urdu media QA, and guardian-threshold calibration remain pending. WhatsApp consent, delivery and guardian alerts are an optional unimplemented milestone. Desktop and mobile browser checks passed for the exercised pages.",
        "",
        "## Demo",
        "",
        "Run `powershell -File scripts/start-demo.ps1`; follow docs/DEMO.md. Open http://localhost:5173/#/analyze. See docs/HANDOFF.md for latest verification and exact continuation state.",
    ]
    (ROOT / "docs/DEMO_REPORT.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    generate()
